cat > /workspace/project/src/star4_switch.c <<'EOF'
/*
 * Offline four-port collective collector.
 *
 * This file intentionally contains no live-I/O code.  It implements the
 * finite replay state machine from PROTOCOL.md.  The public ABI wrappers live
 * in replay_api.c.
 */
#include "epic_clean.h"
#include "offline_api.h"

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define PSN_MASK UINT32_C(0x00ffffff)
#define ALL_RANKS_MASK UINT8_C(0x0f)
#define PORT_BIT(r) ((uint8_t)(1u << (unsigned)(r)))

typedef struct {
    bool in_use;
    uint32_t p;
    uint8_t mask;
    bool complete;
    /* Aggregate primitives use this as D host-endian words.  Broadcast uses
       the first 4D bytes.  Gather uses four consecutive 4D byte records. */
    uint8_t *storage;
} slot_state_t;

typedef struct {
    epic_primitive_t primitive;
    epic_mode_t mode;
    int root;
    uint32_t K;
    uint32_t D;
    uint32_t capacity;
    uint32_t start;
    uint8_t required_mask;

    slot_state_t *slots;
    uint32_t occupied;
    uint32_t retired;

    uint32_t rx_next[4];
    uint32_t up_ready[4];
    uint32_t up_sent[4];
    uint32_t sent_next[4];
    uint32_t ack_next[4];
    bool force_ack[4];

    uint64_t rx_data;
    uint64_t rx_ack;
    uint64_t tx_data;
    uint64_t tx_ack;
    uint64_t accepted;
    uint64_t duplicates;
    uint64_t blocked;
    uint64_t stale;
    uint64_t invalid_wire;
    uint64_t invalid_endpoint;
    uint64_t ack_ignored;
    uint64_t failed_sends;
    uint64_t slot_overwrites;

    epic_emit_fn emit;
    void *user;
} switch_ctx_t;

typedef enum {
    RECORD_AGGREGATE,
    RECORD_RAW,
    RECORD_EMPTY
} record_kind_t;

typedef struct {
    record_kind_t kind;
    const uint32_t *words;
    const uint8_t *raw;
    size_t raw_bytes;
} output_record_t;

static uint32_t payload_bytes(const switch_ctx_t *ctx) {
    return ctx->D * UINT32_C(4);
}

static uint32_t load_be32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}

static uint32_t slot_index(const switch_ctx_t *ctx, uint32_t p) {
    return p % ctx->capacity;
}

static slot_state_t *slot_at(const switch_ctx_t *ctx, uint32_t p) {
    if (p < ctx->retired || (uint64_t)p >= (uint64_t)ctx->retired + ctx->capacity) {
        return NULL;
    }
    slot_state_t *slot = &ctx->slots[slot_index(ctx, p)];
    if (slot->in_use && slot->p == p) {
        return slot;
    }
    return NULL;
}

static void release_slot(switch_ctx_t *ctx, slot_state_t *slot) {
    if (!slot->in_use) {
        return;
    }
    free(slot->storage);
    memset(slot, 0, sizeof(*slot));
    if (ctx->occupied) {
        ctx->occupied--;
    }
}

static slot_state_t *create_slot(switch_ctx_t *ctx, uint32_t p) {
    slot_state_t *slot = &ctx->slots[slot_index(ctx, p)];
    if (slot->in_use) {
        /* With a contiguous retired prefix and a window of exactly N slots,
           an admitted p can never collide with a different live slot.  Keep
           the invariant defensive and never overwrite live data. */
        if (slot->p == p) {
            return slot;
        }
        return NULL;
    }

    size_t bytes = (size_t)payload_bytes(ctx);
    if (ctx->primitive == EPIC_PRIM_ALLGATHER) {
        bytes *= 4u;
    }
    if (bytes != 0) {
        slot->storage = (uint8_t *)malloc(bytes);
        if (!slot->storage) {
            return NULL;
        }
    }
    slot->in_use = true;
    slot->p = p;
    slot->mask = 0;
    slot->complete = false;
    ctx->occupied++;
    return slot;
}

static void add_aggregate(slot_state_t *slot, const uint8_t *payload,
                          uint32_t words, bool first) {
    uint32_t *accum = (uint32_t *)slot->storage;
    for (uint32_t i = 0; i < words; i++) {
        uint32_t value = load_be32(payload + (size_t)i * 4u);
        if (first && slot->mask == 0) {
            accum[i] = value;
        } else {
            accum[i] += value;
        }
    }
}

static int rank_from_ordinal_excluding(int excluded, int ordinal) {
    for (int r = 0; r < 4; r++) {
        if (r == excluded) {
            continue;
        }
        if (ordinal == 0) {
            return r;
        }
        ordinal--;
    }
    return 0;
}

static int ordinal_excluding(int excluded, int rank) {
    int ordinal = 0;
    for (int r = 0; r < 4; r++) {
        if (r == excluded) {
            continue;
        }
        if (r == rank) {
            return ordinal;
        }
        ordinal++;
    }
    return 0;
}

static uint32_t allgather_q(uint32_t p, int dest, int src) {
    return p * UINT32_C(3) + (uint32_t)ordinal_excluding(dest, src);
}

static int reducescatter_dest(const switch_ctx_t *ctx, uint32_t p) {
    return (int)(p / (ctx->K / UINT32_C(4)));
}

static uint32_t reducescatter_q(const switch_ctx_t *ctx, uint32_t p) {
    return p % (ctx->K / UINT32_C(4));
}

static uint32_t output_length(const switch_ctx_t *ctx, int dest) {
    switch (ctx->primitive) {
    case EPIC_PRIM_ALLREDUCE:
        return ctx->K;
    case EPIC_PRIM_REDUCE:
        return dest == ctx->root ? ctx->K : 0;
    case EPIC_PRIM_BCAST:
        return dest == ctx->root ? 0 : ctx->K;
    case EPIC_PRIM_BARRIER:
        return 1;
    case EPIC_PRIM_ALLGATHER:
        return ctx->K * UINT32_C(3);
    case EPIC_PRIM_REDUCESCATTER:
        return ctx->K / UINT32_C(4);
    }
    return 0;
}

static bool describe_output(const switch_ctx_t *ctx, int dest, uint32_t q,
                            output_record_t *record) {
    memset(record, 0, sizeof(*record));
    if (q >= output_length(ctx, dest)) {
        return false;
    }

    uint32_t p;
    slot_state_t *slot;

    switch (ctx->primitive) {
    case EPIC_PRIM_ALLREDUCE:
        p = q;
        slot = slot_at(ctx, p);
        if (!slot || !slot->complete) {
            return false;
        }
        record->kind = RECORD_AGGREGATE;
        record->words = (const uint32_t *)slot->storage;
        return true;
    case EPIC_PRIM_REDUCE:
        if (dest != ctx->root) {
            return false;
        }
        p = q;
        slot = slot_at(ctx, p);
        if (!slot || !slot->complete) {
            return false;
        }
        record->kind = RECORD_AGGREGATE;
        record->words = (const uint32_t *)slot->storage;
        return true;
    case EPIC_PRIM_BCAST:
        if (dest == ctx->root) {
            return false;
        }
        p = q;
        slot = slot_at(ctx, p);
        if (!slot || !slot->complete) {
            return false;
        }
        record->kind = RECORD_RAW;
        record->raw = slot->storage;
        record->raw_bytes = payload_bytes(ctx);
        return true;
    case EPIC_PRIM_BARRIER:
        p = 0;
        slot = slot_at(ctx, p);
        if (!slot || !slot->complete) {
            return false;
        }
        record->kind = RECORD_EMPTY;
        return true;
    case EPIC_PRIM_ALLGATHER: {
        p = q / UINT32_C(3);
        int ordinal = (int)(q % UINT32_C(3));
        int src = rank_from_ordinal_excluding(dest, ordinal);
        slot = slot_at(ctx, p);
        if (!slot || !slot->complete || !(slot->mask & PORT_BIT(src))) {
            return false;
        }
        record->kind = RECORD_RAW;
        record->raw = slot->storage + (size_t)src * payload_bytes(ctx);
        record->raw_bytes = payload_bytes(ctx);
        return true;
    }
    case EPIC_PRIM_REDUCESCATTER:
        p = (uint32_t)dest * (ctx->K / UINT32_C(4)) + q;
        slot = slot_at(ctx, p);
        if (!slot || !slot->complete) {
            return false;
        }
        record->kind = RECORD_AGGREGATE;
        record->words = (const uint32_t *)slot->storage;
        return true;
    }
    return false;
}

static bool contribution_safe(const switch_ctx_t *ctx, int source, uint32_t p) {
    if (ctx->mode == EPIC_MODE_TERMINATION) {
        return true;
    }

    switch (ctx->primitive) {
    case EPIC_PRIM_ALLREDUCE:
        return ctx->ack_next[source] > p;
    case EPIC_PRIM_BARRIER:
        return ctx->ack_next[source] > 0;
    case EPIC_PRIM_REDUCE:
        return ctx->ack_next[ctx->root] > p;
    case EPIC_PRIM_BCAST:
        for (int d = 0; d < 4; d++) {
            if (d == ctx->root) {
                continue;
            }
            if (ctx->ack_next[d] <= p) {
                return false;
            }
        }
        return true;
    case EPIC_PRIM_ALLGATHER:
        for (int d = 0; d < 4; d++) {
            if (d == source) {
                continue;
            }
            if (ctx->ack_next[d] <= allgather_q(p, d, source)) {
                return false;
            }
        }
        return true;
    case EPIC_PRIM_REDUCESCATTER: {
        int dest = reducescatter_dest(ctx, p);
        return ctx->ack_next[dest] > reducescatter_q(ctx, p);
    }
    }
    return false;
}

static void recompute_eligible(switch_ctx_t *ctx) {
    for (int r = 0; r < 4; r++) {
        uint32_t e = ctx->up_ready[r];
        while (e < ctx->rx_next[r] && contribution_safe(ctx, r, e)) {
            e++;
        }
        ctx->up_ready[r] = e;
    }
}

static void advance_received_prefix(switch_ctx_t *ctx, int rank) {
    uint32_t p = ctx->rx_next[rank];
    uint8_t bit = PORT_BIT(rank);
    while (p < ctx->K) {
        slot_state_t *slot = slot_at(ctx, p);
        if (!slot || !(slot->mask & bit)) {
            break;
        }
        p++;
    }
    ctx->rx_next[rank] = p;
}

static bool outputs_acknowledged(const switch_ctx_t *ctx, uint32_t p) {
    switch (ctx->primitive) {
    case EPIC_PRIM_ALLREDUCE:
        for (int r = 0; r < 4; r++) {
            if (ctx->ack_next[r] <= p) {
                return false;
            }
        }
        return true;
    case EPIC_PRIM_REDUCE:
        return ctx->ack_next[ctx->root] > p;
    case EPIC_PRIM_BCAST:
        for (int r = 0; r < 4; r++) {
            if (r == ctx->root) {
                continue;
            }
            if (ctx->ack_next[r] <= p) {
                return false;
            }
        }
        return true;
    case EPIC_PRIM_BARRIER:
        for (int r = 0; r < 4; r++) {
            if (ctx->ack_next[r] <= 0) {
                return false;
            }
        }
        return true;
    case EPIC_PRIM_ALLGATHER:
        for (int d = 0; d < 4; d++) {
            for (int s = 0; s < 4; s++) {
                if (s == d) {
                    continue;
                }
                if (ctx->ack_next[d] <= allgather_q(p, d, s)) {
                    return false;
                }
            }
        }
        return true;
    case EPIC_PRIM_REDUCESCATTER: {
        int dest = reducescatter_dest(ctx, p);
        return ctx->ack_next[dest] > reducescatter_q(ctx, p);
    }
    }
    return false;
}

static bool sources_upstream_acknowledged(const switch_ctx_t *ctx, uint32_t p) {
    for (int r = 0; r < 4; r++) {
        if ((ctx->required_mask & PORT_BIT(r)) && ctx->up_sent[r] <= p) {
            return false;
        }
    }
    return true;
}

static void update_retired(switch_ctx_t *ctx) {
    while (ctx->retired < ctx->K) {
        uint32_t p = ctx->retired;
        slot_state_t *slot = slot_at(ctx, p);
        if (!slot || !slot->complete) {
            break;
        }
        if (!outputs_acknowledged(ctx, p)) {
            break;
        }
        if (!sources_upstream_acknowledged(ctx, p)) {
            break;
        }
        release_slot(ctx, slot);
        ctx->retired++;
    }
}

static uint64_t fold_byte(uint64_t hash, uint8_t value) {
    return (hash ^ (uint64_t)value) * UINT64_C(1099511628211);
}

static uint64_t fold_u64_le(uint64_t hash, uint64_t value) {
    for (int i = 0; i < 8; i++) {
        hash = fold_byte(hash, (uint8_t)(value & 0xffu));
        value >>= 8;
    }
    return hash;
}

void *switch_open(int primitive, int mode, int root, uint32_t count,
                  uint32_t words, uint32_t capacity, uint32_t start,
                  epic_emit_fn emit, void *user) {
    if (primitive < EPIC_PRIM_ALLREDUCE || primitive > EPIC_PRIM_REDUCESCATTER ||
        (mode != EPIC_MODE_NON_TERMINATION && mode != EPIC_MODE_TERMINATION) ||
        root < 0 || root >= EPIC_STAR4_HOSTS || count == 0 || capacity == 0 ||
        words > EPIC_MAX_PAYLOAD_BYTES / 4u || !emit) {
        return NULL;
    }
    if (primitive == EPIC_PRIM_BARRIER && words != 0) {
        return NULL;
    }
    if (primitive == EPIC_PRIM_REDUCESCATTER && (count % 4u) != 0) {
        return NULL;
    }

    switch_ctx_t *ctx = (switch_ctx_t *)calloc(1, sizeof(*ctx));
    if (!ctx) {
        return NULL;
    }
    ctx->primitive = (epic_primitive_t)primitive;
    ctx->mode = (epic_mode_t)mode;
    ctx->root = root;
    ctx->K = count;
    ctx->D = words;
    ctx->capacity = capacity;
    ctx->start = start & PSN_MASK;
    ctx->required_mask = primitive == EPIC_PRIM_BCAST ? PORT_BIT(root) : ALL_RANKS_MASK;
    ctx->emit = emit;
    ctx->user = user;
    ctx->slots = (slot_state_t *)calloc(capacity, sizeof(slot_state_t));
    if (!ctx->slots) {
        free(ctx);
        return NULL;
    }
    return ctx;
}

void switch_close(void *context) {
    switch_ctx_t *ctx = (switch_ctx_t *)context;
    if (!ctx) {
        return;
    }
    for (uint32_t i = 0; i < ctx->capacity; i++) {
        if (ctx->slots[i].in_use) {
            free(ctx->slots[i].storage);
        }
    }
    free(ctx->slots);
    free(ctx);
}

static bool submit_frame(switch_ctx_t *ctx, int rank, const uint8_t *frame,
                         size_t length, bool data) {
    if (!length || !ctx->emit(ctx->user, rank, frame, length)) {
        ctx->failed_sends++;
        return false;
    }
    if (data) {
        ctx->tx_data++;
    } else {
        ctx->tx_ack++;
    }
    return true;
}

static void port_identity(int rank, uint8_t host_mac[6], uint8_t switch_mac[6],
                          uint32_t *host_ip, uint32_t *switch_ip) {
    static const uint8_t host_prefix[5] = {2, 0, 0, 0, 0};
    static const uint8_t switch_prefix[5] = {2, 1, 0, 0, 0};
    memcpy(host_mac, host_prefix, 5);
    memcpy(switch_mac, switch_prefix, 5);
    host_mac[5] = (uint8_t)(rank + 1);
    switch_mac[5] = (uint8_t)(rank + 1);
    *host_ip = htonl(UINT32_C(0x0a000001) + (uint32_t)rank);
    *switch_ip = htonl(UINT32_C(0x0a000065) + (uint32_t)rank);
}

static bool emit_output_record(switch_ctx_t *ctx, int dest, uint32_t q) {
    output_record_t record;
    if (!describe_output(ctx, dest, q, &record)) {
        return false;
    }

    uint8_t host_mac[6], switch_mac[6];
    uint32_t host_ip, switch_ip;
    port_identity(dest, host_mac, switch_mac, &host_ip, &switch_ip);

    uint8_t frame[sizeof(epic_eth_t) + sizeof(epic_ipv4_t) +
                  sizeof(epic_udp_t) + sizeof(epic_bth_t) +
                  EPIC_MAX_PAYLOAD_BYTES + 4];
    uint32_t psn = (ctx->start + q) & PSN_MASK;
    size_t length = 0;

    if (record.kind == RECORD_AGGREGATE) {
        length = epic_build_roce_data(frame, sizeof(frame), switch_mac, host_mac,
                                      switch_ip, host_ip, EPIC_ROCE_UDP_PORT,
                                      EPIC_ROCE_UDP_PORT, UINT32_C(0x100) + (uint32_t)dest,
                                      psn, (const int32_t *)record.words,
                                      (size_t)payload_bytes(ctx));
    } else if (record.kind == RECORD_RAW) {
        length = epic_build_roce_data_raw(frame, sizeof(frame), switch_mac, host_mac,
                                          switch_ip, host_ip, EPIC_ROCE_UDP_PORT,
                                          EPIC_ROCE_UDP_PORT,
                                          UINT32_C(0x100) + (uint32_t)dest, psn,
                                          record.raw, record.raw_bytes);
    } else {
        length = epic_build_roce_data(frame, sizeof(frame), switch_mac, host_mac,
                                      switch_ip, host_ip, EPIC_ROCE_UDP_PORT,
                                      EPIC_ROCE_UDP_PORT, UINT32_C(0x100) + (uint32_t)dest,
                                      psn, NULL, 0);
    }
    if (!length) {
        ctx->failed_sends++;
        return false;
    }
    return submit_frame(ctx, dest, frame, length, true);
}

static bool send_upstream_ack(switch_ctx_t *ctx, int rank) {
    uint32_t eligible = ctx->up_ready[rank];
    if (eligible == 0) {
        return true;
    }
    uint8_t host_mac[6], switch_mac[6];
    uint32_t host_ip, switch_ip;
    port_identity(rank, host_mac, switch_mac, &host_ip, &switch_ip);
    uint8_t frame[sizeof(epic_eth_t) + sizeof(epic_ipv4_t) +
                  sizeof(epic_udp_t) + sizeof(epic_bth_t) +
                  sizeof(epic_aeth_t) + 4];
    uint32_t psn = (ctx->start + eligible - 1u) & PSN_MASK;
    size_t length = epic_build_roce_ack(frame, sizeof(frame), switch_mac, host_mac,
                                       switch_ip, host_ip, EPIC_ROCE_UDP_PORT,
                                       EPIC_ROCE_UDP_PORT,
                                       UINT32_C(0x100) + (uint32_t)rank, psn);
    if (!length) {
        ctx->failed_sends++;
        return false;
    }
    if (!submit_frame(ctx, rank, frame, length, false)) {
        return false;
    }
    ctx->up_sent[rank] = eligible;
    ctx->force_ack[rank] = false;
    return true;
}

static bool service(switch_ctx_t *ctx, int retry_rank) {
    /* Eligible pending upstream ACKs, ascending rank. */
    for (int r = 0; r < 4; r++) {
        bool pending = ctx->force_ack[r] || ctx->up_ready[r] > ctx->up_sent[r];
        if (pending && ctx->up_ready[r] > 0) {
            if (!send_upstream_ack(ctx, r)) {
                return false;
            }
        }
    }

    /* On retry, the selected receiver's sent-but-unacknowledged results. */
    if (retry_rank >= 0 && retry_rank < 4) {
        uint32_t q = ctx->ack_next[retry_rank];
        uint32_t end = ctx->sent_next[retry_rank];
        while (q < end) {
            if (!emit_output_record(ctx, retry_rank, q)) {
                return false;
            }
            q++;
        }
    }

    /* New results, destination rank ascending and q ascending.  A missing
       predecessor at a destination stops that destination's new stream. */
    for (int d = 0; d < 4; d++) {
        uint32_t end = output_length(ctx, d);
        while (ctx->sent_next[d] < end) {
            uint32_t q = ctx->sent_next[d];
            output_record_t probe;
            if (!describe_output(ctx, d, q, &probe)) {
                break;
            }
            if (!emit_output_record(ctx, d, q)) {
                return false;
            }
            ctx->sent_next[d]++;
        }
    }
    return true;
}

static void handle_ack_packet(switch_ctx_t *ctx, int rank,
                              const epic_roce_packet_t *packet) {
    uint32_t prefix = (packet->psn - ctx->start + UINT32_C(1)) & PSN_MASK;
    if (prefix > ctx->ack_next[rank] && prefix <= ctx->sent_next[rank]) {
        ctx->ack_next[rank] = prefix;
        recompute_eligible(ctx);
    } else {
        ctx->ack_ignored++;
    }
    (void)service(ctx, -1);
    update_retired(ctx);
}

static bool source_is_required(const switch_ctx_t *ctx, int rank) {
    return (ctx->required_mask & PORT_BIT(rank)) != 0;
}

static void handle_data_packet(switch_ctx_t *ctx, int rank, uint32_t p,
                               const epic_roce_packet_t *packet) {
    uint8_t bit = PORT_BIT(rank);

    if (p < ctx->retired) {
        ctx->stale++;
        ctx->force_ack[rank] = true;
    } else if ((uint64_t)p >= (uint64_t)ctx->retired + ctx->capacity) {
        ctx->blocked++;
    } else {
        slot_state_t *slot = slot_at(ctx, p);
        if (slot && (slot->mask & bit)) {
            ctx->duplicates++;
            ctx->force_ack[rank] = true;
        } else {
            if (!slot) {
                slot = create_slot(ctx, p);
            }
            if (slot) {
                bool first = (slot->mask == 0);
                switch (ctx->primitive) {
                case EPIC_PRIM_ALLREDUCE:
                case EPIC_PRIM_REDUCE:
                case EPIC_PRIM_REDUCESCATTER:
                    add_aggregate(slot, packet->payload, ctx->D, first);
                    break;
                case EPIC_PRIM_BCAST:
                    if (payload_bytes(ctx) != 0) {
                        memcpy(slot->storage, packet->payload, payload_bytes(ctx));
                    }
                    break;
                case EPIC_PRIM_ALLGATHER:
                    memcpy(slot->storage + (size_t)rank * payload_bytes(ctx),
                           packet->payload, payload_bytes(ctx));
                    break;
                case EPIC_PRIM_BARRIER:
                    break;
                }
                slot->mask |= bit;
                if (slot->mask == ctx->required_mask) {
                    slot->complete = true;
                }
                ctx->accepted++;
                advance_received_prefix(ctx, rank);
                recompute_eligible(ctx);
            }
        }
    }

    (void)service(ctx, -1);
    update_retired(ctx);
}

int switch_ingress(void *context, int rank, const uint8_t *frame, size_t length) {
    switch_ctx_t *ctx = (switch_ctx_t *)context;
    if (!ctx || rank < 0 || rank >= 4) {
        return 0;
    }

    epic_roce_packet_t packet;
    if (!epic_parse_roce(frame, length, &packet)) {
        ctx->invalid_wire++;
        return 0;
    }

    /* The expected vector length is part of wire validity. */
    if (packet.is_data && packet.payload_len != (size_t)payload_bytes(ctx)) {
        ctx->invalid_wire++;
        return 0;
    }

    uint8_t host_mac[6], switch_mac[6];
    uint32_t host_ip, switch_ip;
    port_identity(rank, host_mac, switch_mac, &host_ip, &switch_ip);
    if (memcmp(frame, switch_mac, 6) != 0 ||
        memcmp(frame + 6, host_mac, 6) != 0 ||
        packet.src_ip != host_ip || packet.dst_ip != switch_ip ||
        packet.dst_qpn != UINT32_C(0x200) + (uint32_t)rank) {
        ctx->invalid_endpoint++;
        return 0;
    }

    uint32_t p = 0;
    if (packet.is_data) {
        if (!source_is_required(ctx, rank)) {
            ctx->invalid_endpoint++;
            return 0;
        }
        p = (packet.psn - ctx->start) & PSN_MASK;
        if (p >= ctx->K) {
            ctx->invalid_endpoint++;
            return 0;
        }
        ctx->rx_data++;
        handle_data_packet(ctx, rank, p, &packet);
    } else {
        ctx->rx_ack++;
        handle_ack_packet(ctx, rank, &packet);
    }
    return 1;
}

int switch_flush(void *context) {
    switch_ctx_t *ctx = (switch_ctx_t *)context;
    if (!ctx) {
        return 0;
    }
    bool ok = service(ctx, -1);
    update_retired(ctx);
    return ok ? 1 : 0;
}

int switch_retry(void *context, int rank) {
    switch_ctx_t *ctx = (switch_ctx_t *)context;
    if (!ctx || rank < 0 || rank >= 4) {
        return 0;
    }
    if (ctx->up_ready[rank] > 0) {
        ctx->force_ack[rank] = true;
    }
    bool ok = service(ctx, rank);
    update_retired(ctx);
    return ok ? 1 : 0;
}

void switch_state(void *context, uint64_t *state) {
    switch_ctx_t *ctx = (switch_ctx_t *)context;
    memset(state, 0, 32 * sizeof(*state));
    if (!ctx) {
        return;
    }
    state[0] = ctx->retired;
    state[1] = ctx->occupied;
    for (int r = 0; r < 4; r++) {
        state[2 + r] = ctx->rx_next[r];
        state[6 + r] = ctx->sent_next[r];
        state[10 + r] = ctx->ack_next[r];
        state[14 + r] = ctx->up_sent[r];
    }
    state[18] = ctx->rx_data;
    state[19] = ctx->rx_ack;
    state[20] = ctx->tx_data;
    state[21] = ctx->tx_ack;
    state[22] = ctx->accepted;
    state[23] = ctx->duplicates;
    state[24] = ctx->blocked;
    state[25] = ctx->stale;
    state[26] = ctx->invalid_wire;
    state[27] = ctx->invalid_endpoint;
    state[28] = ctx->ack_ignored;
    state[29] = ctx->failed_sends;
    state[30] = ctx->slot_overwrites;
    state[31] = 0;
}

uint64_t switch_digest(void *context) {
    switch_ctx_t *ctx = (switch_ctx_t *)context;
    uint64_t hash = UINT64_C(14695981039346656037);
    if (!ctx) {
        return hash;
    }

    uint64_t end = (uint64_t)ctx->retired + ctx->capacity;
    if (end > ctx->K) {
        end = ctx->K;
    }
    for (uint32_t p = ctx->retired; (uint64_t)p < end; p++) {
        slot_state_t *slot = slot_at(ctx, p);
        if (!slot) {
            continue;
        }
        hash = fold_u64_le(hash, p);
        hash = fold_byte(hash, slot->mask);
        hash = fold_byte(hash, slot->complete ? 1u : 0u);

        if (ctx->primitive == EPIC_PRIM_ALLGATHER) {
            uint32_t bytes = payload_bytes(ctx);
            for (int r = 0; r < 4; r++) {
                bool present = (slot->mask & PORT_BIT(r)) != 0;
                hash = fold_byte(hash, present ? 1u : 0u);
                if (present) {
                    const uint8_t *raw = slot->storage + (size_t)r * bytes;
                    for (uint32_t i = 0; i < bytes; i++) {
                        hash = fold_byte(hash, raw[i]);
                    }
                }
            }
        } else if (ctx->primitive == EPIC_PRIM_BCAST) {
            uint32_t bytes = payload_bytes(ctx);
            for (uint32_t i = 0; i < bytes; i++) {
                hash = fold_byte(hash, slot->storage[i]);
            }
        } else if (ctx->primitive != EPIC_PRIM_BARRIER) {
            const uint32_t *words = (const uint32_t *)slot->storage;
            for (uint32_t i = 0; i < ctx->D; i++) {
                uint32_t value = words[i];
                for (int j = 0; j < 4; j++) {
                    hash = fold_byte(hash, (uint8_t)(value & 0xffu));
                    value >>= 8;
                }
            }
        }
    }
    return hash;
}
